674	  Let
675	  \[
676	    A_g = \E_{u \sim \F_q^m} A^u_{g(u)}.
677	  \]
678	  Then the primal is
679	  \begin{align}
680	    \sup &\quad \sum_g \,\Tr(T_g \cdot A_g) \label{eq:primal-objective}\\
681	    \text{s.t.} &\quad   T_g \geq 0\qquad\forall g\in\polyfunc{m}{q}{d}, \notag\\
682	    &\quad \sum_g T_g \leq I, \notag
683	  \end{align}
684	  and the dual is
685	  \begin{align}
686	    \inf &\quad \Tr(Z) \label{eq:dual-objective}\\
687	    \text{ s.t.} &\quad Z \geq A_g. \label{eq:dual-constraint}
688	  \end{align}
689	  These semidefinite programs are dual to each other. Moreover there is an optimal pair of solutions $\{T_g\}$ to~\eqref{eq:primal-objective} and $Z$ to~\eqref{eq:dual-objective} such that $\sum_g T_g = I$ and
690	  \begin{equation}\label{eq:slater}
691	    T_g Z  \,=\, T_g {A_g},\qquad\forall g\in \polyfunc{m}{q}{d}.
692	  \end{equation}
693	\end{lemma}
694	\begin{proof}
695	  \uses{lem:sdp-matrix-feasible-bounds}
696	  \leanok
697	  Rewrite~\eqref{eq:primal-objective} in canonical block form. Let $r$ be the dimension of the space on which~$A$ acts, let $M = |\polyfunc{m}{q}{d}|$, and fix an ordering $g_1,\ldots,g_M$ of the polynomials. Consider
698	  \begin{align}
699	    \sup &\quad \Tr(C^\dagger X) \label{eq:primal-canonical}\\
700	    \text{s.t.} &\quad \Tr(D_{ij}^\dagger X) = b_{ij} \qquad\forall i,j\in\{1,\ldots,r\}, \notag\\
701	    &\quad X \geq 0, \notag
702	  \end{align}
703	  where
704	  \[
705	    C = \sum_{i = 1}^M \ket{i}\bra{i} \ot A_{g_i},
706	  \]
707	  and, for $i,j \in \{1,\ldots,r\}$,
708	  \[
709	    D_{ij} = \sum_{k=1}^{M+1} \ket{k}\bra{k} \ot \ket{i}\bra{j},
710	    \qquad
711	    b_{ij}  = \left\{\begin{array}{rl}
712	      1 & \text{if } i = j,\\
713	      0 & \text{otherwise}.
714	    \end{array}\right.
715	  \]
716	  Writing $X=\sum_{i,j=1}^{M+1}\ket{i}\bra{j}\ot X_{ij}$, the constraints say precisely that $\sum_{i=1}^{M+1} X_{ii}=I$, hence $\sum_{i=1}^{M}X_{ii}\le I$, and the objective is
717	  \[
718	    \Tr(C^\dagger X)=\sum_{i=1}^M \Tr(A_{g_i}\cdot X_{ii}).
719	  \]
720	  Thus~\eqref{eq:primal-canonical} is equivalent to~\eqref{eq:primal-objective} under the identification $T_{g_i}=X_{ii}$.
721	
722	  The canonical dual is
723	  \begin{align}
724	    \inf &\quad \sum_i\, z_{ij} b_{ij} \label{eq:dual-canonical}\\
725	    \text{s.t.} &\quad  \sum_{i,j} \,z_{ij} D_{ij} \geq C. \label{eq:dual-canonical-constraint}
726	  \end{align}
727	  Since
728	  \[
729	    \sum_{i,j=1}^r z_{ij} D_{ij}
730	    = \sum_{k=1}^{M+1} \ket{k}\bra{k} \ot \left(\sum_{i,j=1}^r z_{ij}\ket{i}\bra{j}\right)
731	    =: \sum_{k=1}^{M+1}\ket{k}\bra{k} \ot Z,
732	  \]
733	  the constraint~\eqref{eq:dual-canonical-constraint} is exactly $Z\ge A_{g_i}$ for every $i$, and the objective is $\Tr(Z)$.  In Lean, the latter statement is recorded as the trace-pairing identity
734	  \[
735	    \Re\Tr(D(Z)X)=\Re\Tr(Z)
736	  \]
737	  for every feasible canonical primal matrix \(X\), where \(D(Z)\) denotes the
738	  block-diagonal canonical dual operator.  Consequently the canonical
739	  primal-dual gap is the real trace pairing of \(X\) with the canonical dual
740	  slack \(D(Z)-C\).  Since the real trace pairing of positive semidefinite
741	  operators is nonnegative, Lean also records the resulting weak-duality
742	  inequality for any feasible canonical primal and dual pair.
743	  Hence~\eqref{eq:dual-canonical} is equivalent to~\eqref{eq:dual-objective}.
744	
745	  Slater's condition holds because
746	  \[
747	    T_g = \frac{1}{2M}\cdot I \qquad\forall g\in\polyfunc{m}{q}{d},
748	    \qquad
749	    Z = 2I
750	  \]
751	  are strictly feasible for the primal and dual respectively. Therefore strong duality holds. For an optimal pair $(X,(z_{ij}))$ in canonical form, complementary slackness gives
752	  \begin{equation}\label{eq:complementary-slackness}
753	    X\Big( \sum_{i,j} \,z_{ij} D_{ij} - C \Big) \,=\, 0.
754	  \end{equation}
755	  We may assume that $X$ is block diagonal.
756	  Translating~\eqref{eq:complementary-slackness} back to the variables
757	  $\{T_g\}$ and~$Z$ yields $T_g(Z-A_g)=0$ for every~$g$ and \(S Z=0\), where
758	  \(S=I-\sum_gT_g\) is the slack block.
759	  The paper then treats this as forcing \(S=0\).  The Lean development records
760	  this saturation as part of the canonical optimal-pair datum for the block

