 92	\begin{lemma}[Projectivity of the single-basis marginals]\label{lem:s-w-marginals-projective}
 93		\lean{MIPStarRE.QPBT.GlobalPairWitness.marginalPoly_isProjective}
 94		\leanok
 95		\uses{def:s-w-marginals, lem:qld-4-7}
 96		For each $W\in\{X,Z\}$, the family $\{\hat{S}^W_g\}_g$ is a projective measurement with outcomes in $\mathrm{ideg}_{d,m}(\F_q)$.
 97	\end{lemma}
