100		\lean{MIPStarRE.QPBT.tauDotProj}
101		\leanok
102		\uses{def:generalized-pauli}
103		For $W \in \{X,Z\}$ and $h \in \F_q^{M}$ let $\tau^W_h$ denote the projector corresponding to measuring $(\C^q)^{\ot M}$ in the $W$ basis and obtaining the outcome $h$ (Definition~\ref{def:generalized-pauli}). For all $W \in \{X,Z\}$, $\tilde{u} \in \F_q^{M}$, and $a \in \F_q$, define the operator
104		\begin{equation}\label{eq:def-tauwu}
105			\tau^{W}_{a}(\tilde{u}) = \sum_{h \in \F_q^{M} \,:\, h \cdot \tilde{u} = a} \tau^W_{h}\;.
106		\end{equation}
