109	\begin{lemma}[Projectivity and completeness of the dot-product operators]\label{lem:tau-dot-product-projective}
110		\lean{MIPStarRE.QPBT.tauDotProj_isProj, MIPStarRE.QPBT.sum_tauDotProj_eq_one}
