112		\uses{def:tau-dot-product-projector, def:generalized-pauli}
113		For each fixed $W$ and $\tilde{u}$, every $\tau^W_a(\tilde{u})$ is a projector and
114		$\sum_{a\in\F_q}\tau^W_a(\tilde{u})=\Id$. Thus
115		$\{\tau^W_a(\tilde{u})\}_{a\in\F_q}$ is a projective measurement.
116	\end{lemma}
