354	\sum_h \bra{\psi} H_h \otimes I \ket{\psi}
355	& = \E_{\bu} \sum_h \bra{\psi} H^{\bu}_h \otimes I \ket{\psi}\nonumber\\
356	&= \E_{\bu} \sum_h \bra{\psi} (A^{\bu}_{h(\bu)} \cdot T_h \cdot A^{\bu}_{h(\bu)}) \otimes I \ket{\psi}\nonumber\\
