359	We claim that
360	\begin{equation}\label{eq:yet-another-move-a}
361	\eqref{eq:bracketize-the-expression}
362	\approx_{2\sqrt{\delta}}
363	\E_{\bu} \sum_a \bra{\psi} ( T_{[h(\bu)=a]} \cdot A^{\bu}_{a}) \otimes A^{\bu}_{a} \ket{\psi}.
364	\end{equation}
365	To show this, we bound the magnitude of the difference
366	\begin{multline*}
367	\Big|\E_{\bu} \sum_a \bra{\psi} (A^{\bu}_{a} \otimes I - I \otimes A^{\bu}_{a}) \cdot (( T_{[h(\bu) = a]} \cdot A^{\bu}_{a}) \otimes I) \ket{\psi}\Big|\\
368	\leq
369	\sqrt{\E_{\bu} \sum_a \bra{\psi} (A^{\bu}_{a} \otimes I - I \otimes A^{\bu}_{a})^2 \ket{\psi}}
370	\cdot \sqrt{\E_{\bu} \sum_a \bra{\psi} (A^{\bu}_{a} \cdot  T^2_{[h(\bu) = a]} \cdot A^{\bu}_{a}) \otimes I \ket{\psi}}.
371	\end{multline*}
372	The expression inside the first square root is at most $2\delta \leq 4 \delta$
373	by \Cref{prop:simeq-to-approx} and the self-consistency of~$A$,
374	and the expression inside the second square root is at most~$1$ because $T_{[h(\bu) = a]} \leq I$.
375	Next, we claim that 
376	\begin{equation}\label{eq:mysterious-case-of-the-disappearing-a}
